-- HawkTokai core: one set of rules for every extra, so theme, fonts, saving and empty states stay in sync with Airflow.
-- load it first, right after HawkTokai.lua: loadstring(readfile("HawkTokai/Core.lua"))()(HawkTokai)
-- lives in its own file, so a bug here cannot stop HawkTokai.lua from loading.
do
local okMod, errMod = pcall(function(Lib)
    if Lib.UI ~= nil then
        return true
    end

    local FALLBACK = {
        Background = Color3.fromRGB(20, 20, 24),
        Surface = Color3.fromRGB(26, 26, 32),
        Surface2 = Color3.fromRGB(32, 32, 40),
        Surface3 = Color3.fromRGB(44, 44, 54),
        Stroke = Color3.fromRGB(46, 46, 56),
        StrokeHover = Color3.fromRGB(80, 80, 96),
        Accent = Color3.fromRGB(230, 168, 86),
        AccentDark = Color3.fromRGB(24, 18, 26),
        Text = Color3.fromRGB(235, 235, 240),
        Muted = Color3.fromRGB(140, 140, 152),
    }

    -- the properties Airflow's recolour pass also touches
    local THEME_PROPERTIES = { "BackgroundColor3", "TextColor3", "PlaceholderColor3", "ImageColor3", "ScrollBarImageColor3" }

    -- screen GUIs that live outside a window (keybind HUD, info HUD). they get the same recolour as window pieces
    local tracked = setmetatable({}, { __mode = "k" })

    local UI = {}

    -- the live colour for a theme key. read when a piece is built, so pieces built after SetTheme get the new colours
    function UI.color(key)
        local theme = Lib.Theme
        if type(theme) == "table" and typeof(theme[key]) == "Color3" then
            return theme[key]
        end
        return FALLBACK[key] or Color3.new(1, 1, 1)
    end

    -- the library's own font objects: Regular, Medium, Bold. LoadFont swaps them in place
    function UI.font(kind)
        local fonts = Lib.Fonts
        if type(fonts) == "table" and typeof(fonts[kind]) == "Font" then
            return fonts[kind]
        end
        local ok, fallback = pcall(Font.fromEnum, Enum.Font.Gotham)
        if ok then
            return fallback
        end
        return Font.new("rbxasset://fonts/families/BuilderSans.json")
    end

    -- a screen GUI that is not part of a window. SetTheme recolours it from now on
    function UI.track(gui)
        if typeof(gui) == "Instance" then
            tracked[gui] = true
        end
        return gui
    end

    -- a handle gets the same fields Airflow's own elements get, so SaveConfig writes it and LoadConfig sets it.
    -- the handle needs Get() and Set(value, skipCallback)
    function UI.register(Window, handle, flag, kind)
        handle._type = kind
        handle._listeners = handle._listeners or {}
        if type(flag) == "string" and flag ~= "" then
            Lib.Flags[flag] = handle
            if Window and type(Window.Flags) == "table" then
                Window.Flags[flag] = handle
            end
        end
        return handle
    end

    -- the autosave Airflow runs after a flagged change
    function UI.changed(Window, flag)
        if type(flag) == "string" and flag ~= "" and Window and type(Window._autoSave) == "function" then
            Window:_autoSave()
        end
    end

    -- Airflow shows a 200x70 holder directly on the page while a tab has no elements
    function UI.emptyHolder(tab)
        local page = tab and tab._page
        if typeof(page) ~= "Instance" then
            return nil
        end
        for _, child in ipairs(page:GetChildren()) do
            if child:IsA("Frame") and child.Size.X.Offset == 200 and child.Size.Y.Offset == 70 then
                return child
            end
        end
        return nil
    end

    -- sub-lists and columns hide the tab's own list, so Airflow's empty check cannot see their elements.
    -- this counts the elements in every one of them instead
    function UI.linkEmpty(tab, lists)
        local holder = UI.emptyHolder(tab)
        if not holder then
            return
        end
        local function refresh()
            local count = 0
            for _, list in ipairs(lists) do
                for _, child in ipairs(list:GetChildren()) do
                    if child:IsA("GuiObject") then
                        count += 1
                    end
                end
            end
            holder.Visible = count == 0
        end
        for _, list in ipairs(lists) do
            list.ChildAdded:Connect(refresh)
            list.ChildRemoved:Connect(refresh)
        end
        refresh()
    end

    local function snapshot()
        local out = {}
        local theme = Lib.Theme
        if type(theme) == "table" then
            for key, value in pairs(theme) do
                if typeof(value) == "Color3" then
                    out[key] = value
                end
            end
        end
        return out
    end

    -- replaces every colour in the tree whose hex is an old theme colour with its new theme colour
    local function recolor(root, mapping)
        local function apply(obj)
            for _, property in ipairs(THEME_PROPERTIES) do
                local ok, value = pcall(function()
                    return obj[property]
                end)
                if ok and typeof(value) == "Color3" then
                    local new = mapping[value:ToHex()]
                    if new ~= nil then
                        pcall(function()
                            obj[property] = new
                        end)
                    end
                end
            end
            if obj:IsA("UIStroke") then
                local new = mapping[obj.Color:ToHex()]
                if new ~= nil then
                    obj.Color = new
                end
            end
        end
        apply(root)
        for _, obj in ipairs(root:GetDescendants()) do
            apply(obj)
        end
    end

    -- wraps Airflow's SetTheme: window pieces are recoloured by Airflow itself, tracked GUIs are recoloured here
    local originalSetTheme = Lib.SetTheme
    if type(originalSetTheme) == "function" then
        Lib.SetTheme = function(self, ...)
            local before = snapshot()
            local result = originalSetTheme(self, ...)
            local after = snapshot()
            local mapping = {}
            for key, old in pairs(before) do
                local new = after[key]
                if new ~= nil and old:ToHex() ~= new:ToHex() then
                    mapping[old:ToHex()] = new
                end
            end
            for gui in pairs(tracked) do
                if gui.Parent ~= nil then
                    recolor(gui, mapping)
                end
            end
            return result
        end
    end

    Lib.UI = UI
    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Core failed: " .. tostring(errMod)) end
end
-- HawkTokai extras: keybind HUD, corner glow, per-feature keybinds.
-- lives in its own file, so a bug here cannot stop HawkTokai.lua from loading.
-- usage: loadstring(readfile("HawkTokai/Extras.lua"))()(HawkTokai)
do
local okMod, errMod = pcall(function(Lib)
    local TweenService = game:GetService("TweenService")
    local RunService = game:GetService("RunService")

    -- colours and fonts come from the live theme and the library fonts (Core.lua), read where each piece is built
    local FALLBACK_HUD = {
        Panel = Color3.fromRGB(20, 20, 24),
        Stroke = Color3.fromRGB(46, 46, 56),
        Muted = Color3.fromRGB(140, 140, 152),
        Accent = Color3.fromRGB(230, 168, 86),
    }
    local THEME_KEY = { Panel = "Surface", Stroke = "Stroke", Muted = "Muted", Accent = "Accent", Background = "Background" }
    local function themeColor(name)
        if Lib.UI then
