            local anyOn = false
            for _, row in ipairs(hud._rows) do
                local okOn, on = pcall(function() return row.toggle:Get() == true end)
                on = okOn and on == true
                if on then anyOn = true end

                local okKey, key = pcall(function() return row.bind:Get() end)
                local keyText = "--"
                if okKey and typeof(key) == "EnumItem" then keyText = key.Name end
                row.label.Text = keyText .. "  " .. row.name

                -- colour changes only when the state changes
                if on ~= row.on then
                    row.on = on
                    local target = on and themeColor("Accent") or themeColor("Muted")
                    tween(row.label, 0.2, Enum.EasingStyle.Quint, { TextColor3 = target }):Play()
