        function hud:Track(name, toggle, bind)
            local row = Instance.new("TextLabel")
            row.Name = tostring(name)
            row.BackgroundTransparency = 1
            row.Size = UDim2.new(1, 0, 0, 18)
            row.FontFace = fontOf("Regular")
            row.TextSize = 14
            row.TextXAlignment = Enum.TextXAlignment.Left
            row.TextColor3 = themeColor("Muted")
            row.TextTransparency = 1
            row.Text = ""
            row.LayoutOrder = #hud._rows + 1
            row.Parent = panel

            -- thin bar on the left edge of the row, its colour follows the state
            local bar = Instance.new("Frame")
            bar.Name = "Bar"
            bar.BackgroundColor3 = themeColor("Muted")
            bar.BorderSizePixel = 0
            bar.Size = UDim2.new(0, 2, 1, 0)
            bar.Parent = row

