                place()
            end
        end

        function hud:SetVisible(on)
            fade(on == true)
        end

        function hud:Destroy()
            hud._destroyed = true
            for _, conn in ipairs(hud._conns) do conn:Disconnect() end
            gui:Destroy()
        end

        Lib._hud = hud
        return hud
    end

    -- one feature with its own key. group is a tab or groupbox.
    -- Mode "Toggle": each press flips it. Mode "Hold": on while the key is held.
    -- returns the toggle and the keybind. both have Set and Get.
    function Lib:AddFeature(group, opts)
        opts = opts or {}
        local name = tostring(opts.Name or "Feature")
        local hold = opts.Mode == "Hold"

        local toggle = group:CreateToggle({
            Name = name,
            Default = opts.Default == true,
            Flag = opts.Flag,
            Callback = opts.Callback,
        })

        local bind = group:CreateKeybind({
            Name = name .. " key",
            Default = opts.Key,
            Mode = hold and "Hold" or "Toggle",
            Flag = opts.Flag and (opts.Flag .. "_key") or nil,
            Callback = function(value)
                if hold then
                    toggle:Set(value == true)
                else
                    toggle:Set(not toggle:Get())
                end
            end,
        })

        if Lib._hud then
            Lib._hud:Track(name, toggle, bind)
        end
        return toggle, bind
    end


    -- tab effects, two sides of the window:
    -- left (tab list): an accent bar under the selected tab grows and shrinks.
    -- right (content): a short dark fade over the content on every page change.
    -- wraps Window:SelectTab, so the original selection still runs.
    function Lib:AddTabEffects(Window)
        local content = Window.Content
        if typeof(content) ~= "Instance" then return false end
        if type(Window.SelectTab) ~= "function" then return false end
        local originalSelect = Window.SelectTab

        local overlay = Instance.new("Frame")
        overlay.Name = "TabFade"
        overlay.Size = UDim2.fromScale(1, 1)
        overlay.BackgroundColor3 = themeColor("Background")
        overlay.BackgroundTransparency = 1
        overlay.BorderSizePixel = 0
        overlay.ZIndex = 50
        overlay.Parent = content

        local function ensureBar(tab)
            if tab._fxBar or typeof(tab._button) ~= "Instance" then return end
            local bar = Instance.new("Frame")
            bar.Name = "TabAccent"
            bar.AnchorPoint = Vector2.new(0.5, 1)
            bar.Position = UDim2.new(0.5, 0, 1, -2)
            bar.Size = UDim2.new(0, 0, 0, 2)
            bar.BackgroundColor3 = themeColor("Accent")
            bar.BorderSizePixel = 0
            bar.ZIndex = tab._button.ZIndex + 1
            bar.Parent = tab._button
            tab._fxBar = bar
        end

        local function syncBars(animate)
            for _, tab in ipairs(Window.Tabs or {}) do
                ensureBar(tab)
                local bar = tab._fxBar
                if bar then
                    local size = (tab == Window.CurrentTab) and UDim2.new(0.8, 0, 0, 2) or UDim2.new(0, 0, 0, 2)
