        function Window:SelectTab(...)
            local before = self.CurrentTab
            local result = originalSelect(self, ...)
            if self.CurrentTab ~= before then
                syncBars(true)
                overlay.BackgroundTransparency = 0.55
                tween(overlay, 0.4, Enum.EasingStyle.Quad, { BackgroundTransparency = 1 }):Play()
            end
