-- HawkTokai effects: halos at two corners and a zoom when the page changes, and fades at the scroll edges.
-- every scrolling list on a page gets the fades, sub-tab and column lists included. colours follow the live theme.
-- lives in its own file, so a bug here cannot stop HawkTokai.lua from loading. needs Core.lua first.
-- usage: loadstring(readfile("HawkTokai/Effects.lua"))()(HawkTokai)
--   local page = HawkTokai:AddPageEffects(Window)     page:SetEnabled(false)
--   local fades = HawkTokai:AddScrollFades(Window)    fades:SetEnabled(false)
do
local okMod, errMod = pcall(function(Lib)
    if not Lib.UI then
        warn("[HawkTokai] Effects.lua needs Core.lua loaded first")
        return false
    end
    local UI = Lib.UI

    local TweenService = game:GetService("TweenService")
    local RunService = game:GetService("RunService")
    local FADE_HEIGHT = 22

    local function tween(obj, seconds, props)
        return TweenService:Create(obj, TweenInfo.new(seconds, Enum.EasingStyle.Quint), props)
    end

    -- one halo centred on a corner of the content. it grows and fades in about half a second.
    -- ZIndex 60 keeps it above the dark TabFade overlay from AddTabEffects
    local function flashCorner(content, position)
        local halo = Instance.new("Frame")
        halo.Name = "PageHalo"
        halo.AnchorPoint = Vector2.new(0.5, 0.5)
        halo.Position = position
        halo.Size = UDim2.fromOffset(40, 40)
        halo.BackgroundColor3 = UI.color("Accent")
        halo.BackgroundTransparency = 0.4
        halo.BorderSizePixel = 0
        halo.ZIndex = 60
        halo.Parent = content
        local round = Instance.new("UICorner")
        round.CornerRadius = UDim.new(1, 0)
        round.Parent = halo
        tween(halo, 0.6, { Size = UDim2.fromOffset(320, 320), BackgroundTransparency = 1 }):Play()
        task.delay(0.65, function()
            halo:Destroy()
        end)
    end

    -- the new page starts at 96.5 percent and settles to full size
    local function zoomIn(page)
        local scale = page:FindFirstChild("PageZoom")
        if not scale then
            scale = Instance.new("UIScale")
            scale.Name = "PageZoom"
            scale.Parent = page
        end
        scale.Scale = 0.965
        tween(scale, 0.4, { Scale = 1 }):Play()
        task.delay(0.45, function()
            if scale.Parent then
                scale:Destroy()
            end
        end)
    end

    -- top and bottom edge fades for one scrolling list, placed on the list's own edges so columns and sub-lists work too
    local function makeFades(page, list)
        local function build(isTop)
            local fade = Instance.new("Frame")
            fade.Name = isTop and "FadeTop" or "FadeBottom"
            fade.BackgroundColor3 = UI.color("Background")
            fade.BackgroundTransparency = 1
            fade.BorderSizePixel = 0
            fade.Active = false
            fade.ZIndex = 4
            local pos = list.Position
            local size = list.Size
            if isTop then
                fade.Position = UDim2.new(pos.X.Scale, pos.X.Offset, pos.Y.Scale, pos.Y.Offset)
            else
                fade.Position = UDim2.new(
                    pos.X.Scale,
                    pos.X.Offset,
                    pos.Y.Scale + size.Y.Scale,
                    pos.Y.Offset + size.Y.Offset - FADE_HEIGHT
                )
            end
            fade.Size = UDim2.new(size.X.Scale, size.X.Offset, 0, FADE_HEIGHT)
            fade.Parent = page

            local grad = Instance.new("UIGradient")
            grad.Rotation = 90
            if isTop then
                grad.Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0.05),
                    NumberSequenceKeypoint.new(1, 1),
                })
            else
                grad.Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(1, 0.05),
                })
            end
            grad.Parent = fade
            return fade
        end
        return { top = build(true), bottom = build(false), topOn = false, bottomOn = false }
    end

    -- a fade shows only while its list is visible, can scroll that way, and the fades are enabled
    local function updateFades(fades, list, enabled)
        local range = math.max(list.AbsoluteCanvasSize.Y - list.AbsoluteWindowSize.Y, 0)
        local y = list.CanvasPosition.Y
        local active = enabled and list.Visible and range > 0
        local wantTop = active and y > 2
        local wantBottom = active and y < range - 2
        if wantTop ~= fades.topOn then
            fades.topOn = wantTop
            fades.top.BackgroundColor3 = UI.color("Background")
            tween(fades.top, 0.2, { BackgroundTransparency = wantTop and 0 or 1 }):Play()
        end
        if wantBottom ~= fades.bottomOn then
            fades.bottomOn = wantBottom
            fades.bottom.BackgroundColor3 = UI.color("Background")
            tween(fades.bottom, 0.2, { BackgroundTransparency = wantBottom and 0 or 1 }):Play()
        end
    end

    -- page change: two halos at the top-left and bottom-right of the content, and the page zooms in
    function Lib:AddPageEffects(Window)
        local content = Window.Content
        if typeof(content) ~= "Instance" or type(Window.SelectTab) ~= "function" then
            return nil
        end
        local originalSelect = Window.SelectTab
        local api = { enabled = true }

        function Window:SelectTab(...)
            local before = self.CurrentTab
            local result = originalSelect(self, ...)
            local now = self.CurrentTab
            if api.enabled and now and now ~= before and typeof(now._page) == "Instance" then
                zoomIn(now._page)
                flashCorner(content, UDim2.new(0, 0, 0, 0))
                flashCorner(content, UDim2.new(1, 0, 1, 0))
            end
            return result
        end

        function api:SetEnabled(on)
            api.enabled = on == true
        end

        return api
    end

    -- scroll edges: every scrolling list on every tab, including lists added after this call
    function Lib:AddScrollFades(Window)
        if type(Window.Tabs) ~= "table" then
            return nil
        end
        local api = { enabled = true }
        local tracked = setmetatable({}, { __mode = "k" })

        local connection = RunService.RenderStepped:Connect(function()
            for _, tab in ipairs(Window.Tabs) do
                local page = tab._page
                if typeof(page) == "Instance" then
                    for _, child in ipairs(page:GetChildren()) do
                        if child:IsA("ScrollingFrame") and tracked[child] == nil then
                            tracked[child] = makeFades(page, child)
                        end
                    end
                end
            end
            for list, fades in pairs(tracked) do
                if list.Parent ~= nil then
                    updateFades(fades, list, api.enabled)
                else
                    tracked[list] = nil
                end
            end
        end)

        function api:SetEnabled(on)
            api.enabled = on == true
        end

        function api:Destroy()
            connection:Disconnect()
        end

        return api
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Effects failed: " .. tostring(errMod)) end
end
-- HawkTokai menu search: a box at the top-right of the content. type to list the matching controls on every tab.
-- click a result to jump to its tab, scroll to the card and flash it. ctrl+f focuses the box, esc clears it.
-- lives in its own file, so a bug here cannot stop HawkTokai.lua from loading.
-- usage: loadstring(readfile("HawkTokai/Search.lua"))()(HawkTokai)  then  HawkTokai:AddMenuSearch(Window)
do
local okMod, errMod = pcall(function(Lib)
    if not Lib.UI then
        warn("[HawkTokai] Search.lua needs Core.lua loaded first")
        return false
    end
    local UI = Lib.UI
    local TweenService = game:GetService("TweenService")
    local UserInputService = game:GetService("UserInputService")

    local FALLBACK = {
        Surface = Color3.fromRGB(24, 24, 30),
        Surface2 = Color3.fromRGB(30, 30, 38),
        Stroke = Color3.fromRGB(46, 46, 56),
        Accent = Color3.fromRGB(230, 168, 86),
        Text = Color3.fromRGB(235, 235, 240),
        Muted = Color3.fromRGB(140, 140, 152),
    }
    local MAX_RESULTS = 8
    local ROW_HEIGHT = 30
    local PANEL_WIDTH = 240

    -- reads the live theme, so a SetTheme call is picked up by the next search
    local function color(key)
        local theme = Lib.Theme
        local value = nil
        if type(theme) == "table" then
            value = theme[key]
        end
        if typeof(value) == "Color3" then
            return value
        end
        return FALLBACK[key]
    end

    local function tween(obj, seconds, props)
        return TweenService:Create(obj, TweenInfo.new(seconds, Enum.EasingStyle.Quint), props)
    end

    local function round(parent, radius)
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, radius)
        corner.Parent = parent
    end

    local function outline(parent)
        local stroke = Instance.new("UIStroke")
        stroke.Color = color("Stroke")
        stroke.Thickness = 1
        stroke.Parent = parent
        return stroke
    end

    local function inside(obj, point)
        local origin, size = obj.AbsolutePosition, obj.AbsoluteSize
        return point.X >= origin.X and point.X <= origin.X + size.X and point.Y >= origin.Y and point.Y <= origin.Y + size.Y
    end

    -- the text a card is searched by: its Title label, else the first text inside it, else nothing
    local function cardText(card)
        if card:IsA("TextLabel") then
            if card.Text ~= "" then
                return card.Text
            end
            return nil
        end
        local title = card:FindFirstChild("Title", true)
        if title and title:IsA("TextLabel") and title.Text ~= "" then
            return title.Text
        end
        for _, descendant in ipairs(card:GetDescendants()) do
            if descendant:IsA("TextLabel") and descendant.Text ~= "" then
                return descendant.Text
            end
        end
        return nil
    end

