        box.Position = UDim2.new(1, -56, 0, 14)
        box.Size = UDim2.fromOffset(180, 30)
        box.BackgroundColor3 = color("Surface")
        box.BorderSizePixel = 0
        box.ZIndex = 10
        box.Parent = content
        round(box, 6)
        outline(box)

        local input = Instance.new("TextBox")
