        input.BackgroundTransparency = 1
        input.Position = UDim2.fromOffset(10, 0)
        input.Size = UDim2.new(1, -20, 1, 0)
        input.FontFace = UI.font("Regular")
        input.TextSize = 13
        input.TextColor3 = color("Text")
        input.PlaceholderText = "search  (ctrl+f)"
        input.PlaceholderColor3 = color("Muted")
        input.Text = ""
        input.ClearTextOnFocus = false
        input.TextXAlignment = Enum.TextXAlignment.Left
        input.ZIndex = 11
        input.Parent = box

        local panel = Instance.new("Frame")
        panel.Name = "Results"
        panel.AnchorPoint = Vector2.new(1, 0)
        panel.Position = UDim2.new(1, -56, 0, 50)
        panel.Size = UDim2.fromOffset(PANEL_WIDTH, 0)
        panel.AutomaticSize = Enum.AutomaticSize.Y
        panel.BackgroundColor3 = color("Surface2")
        panel.BorderSizePixel = 0
        panel.Visible = false
        panel.ZIndex = 12
        panel.Parent = content
        round(panel, 8)
        outline(panel)
        local padding = Instance.new("UIPadding")
        padding.PaddingTop = UDim.new(0, 4)
        padding.PaddingBottom = UDim.new(0, 4)
        padding.PaddingLeft = UDim.new(0, 4)
        padding.PaddingRight = UDim.new(0, 4)
        padding.Parent = panel
        local layout = Instance.new("UIListLayout")
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, 2)
        layout.Parent = panel

        local rows = {}
        local focused = false

        local function clearRows()
            for _, row in ipairs(rows) do
                row:Destroy()
            end
            table.clear(rows)
        end

        -- every visible card on every tab whose text contains the query, capped at MAX_RESULTS
        local function findMatches(query)
            local found = {}
            for _, tab in ipairs(Window.Tabs) do
                local list = tab.List
                if typeof(list) == "Instance" then
                    for _, card in ipairs(list:GetChildren()) do
                        if card:IsA("GuiObject") and card.Visible then
                            local text = cardText(card)
                            if text and string.find(string.lower(text), query, 1, true) then
                                table.insert(found, { tab = tab, card = card, text = text })
                                if #found >= MAX_RESULTS then
                                    return found
                                end
                            end
                        end
                    end
                end
            end
            return found
        end

        local function jump(match)
            panel.Visible = false
            Window:SelectTab(match.tab)
            task.delay(0.36, function()
                local list, card = match.tab.List, match.card
                if not (list and list.Parent and card and card.Parent) then
                    return
                end
                local y = card.AbsolutePosition.Y - list.AbsolutePosition.Y + list.CanvasPosition.Y - 12
                list.CanvasPosition = Vector2.new(0, math.max(y, 0))
                flash(card)
            end)
        end

        local function makeRow(text, where, match)
            local row = Instance.new("TextButton")
            row.Text = ""
            row.AutoButtonColor = false
            row.BackgroundColor3 = color("Surface")
            row.BackgroundTransparency = 1
            row.BorderSizePixel = 0
            row.Size = UDim2.new(1, 0, 0, ROW_HEIGHT)
            row.LayoutOrder = #rows + 1
            row.ZIndex = 13
            row.Parent = panel
            round(row, 6)

            local name = Instance.new("TextLabel")
            name.BackgroundTransparency = 1
            name.Position = UDim2.fromOffset(8, 0)
            name.Size = UDim2.new(1, -110, 1, 0)
            name.FontFace = UI.font("Medium")
            name.Text = text
            name.TextSize = 13
            name.TextColor3 = match and color("Text") or color("Muted")
            name.TextXAlignment = Enum.TextXAlignment.Left
            name.TextTruncate = Enum.TextTruncate.AtEnd
            name.ZIndex = 14
            name.Parent = row

            local tabLabel = Instance.new("TextLabel")
            tabLabel.BackgroundTransparency = 1
            tabLabel.AnchorPoint = Vector2.new(1, 0)
            tabLabel.Position = UDim2.new(1, -8, 0, 0)
            tabLabel.Size = UDim2.new(0, 96, 1, 0)
            tabLabel.FontFace = UI.font("Regular")
            tabLabel.Text = where
            tabLabel.TextSize = 12
            tabLabel.TextColor3 = color("Muted")
            tabLabel.TextXAlignment = Enum.TextXAlignment.Right
            tabLabel.TextTruncate = Enum.TextTruncate.AtEnd
            tabLabel.ZIndex = 14
            tabLabel.Parent = row

            if match then
                row.MouseEnter:Connect(function()
                    tween(row, 0.12, { BackgroundTransparency = 0.3 }):Play()
                end)
                row.MouseLeave:Connect(function()
                    tween(row, 0.2, { BackgroundTransparency = 1 }):Play()
                end)
                row.MouseButton1Click:Connect(function()
                    jump(match)
                end)
            end
            table.insert(rows, row)
            return row
        end

        local function render()
            clearRows()
            local query = string.lower(input.Text)
            if query == "" then
                panel.Visible = false
                return
            end
            local matches = findMatches(query)
            if #matches == 0 then
                makeRow("no matches", "", nil)
            else
                for _, match in ipairs(matches) do
                    makeRow(match.text, tostring(match.tab.Name or ""), match)
                end
            end
            panel.Visible = true
        end

        input:GetPropertyChangedSignal("Text"):Connect(render)
        input.Focused:Connect(function()
            focused = true
        end)
        input.FocusLost:Connect(function()
            focused = false
        end)

        UserInputService.InputBegan:Connect(function(io, processed)
            if processed then
                return
            end
            if io.KeyCode == Enum.KeyCode.F and (UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)) then
                input:CaptureFocus()
            elseif io.KeyCode == Enum.KeyCode.Escape and focused then
                input.Text = ""
                input:ReleaseFocus()
            end
        end)

        -- a click outside the box and the results closes the results
        UserInputService.InputBegan:Connect(function(io)
            if io.UserInputType ~= Enum.UserInputType.MouseButton1 and io.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            if not panel.Visible then
                return
            end
            local point = UserInputService:GetMouseLocation()
            if not inside(panel, point) and not inside(box, point) then
                panel.Visible = false
            end
        end)

        return true
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Search failed: " .. tostring(errMod)) end
end
-- HawkTokai info HUD: a watermark and small info rows (fps, ping, time, player, game, custom) in a screen corner.
-- its own screen GUI, tracked by Core so SetTheme recolours it. lives in its own file, so a bug here cannot stop HawkTokai.lua from loading.
-- needs Core.lua loaded first. usage: loadstring(readfile("HawkTokai/InfoHud.lua"))()(HawkTokai)
--   local info = HawkTokai:CreateInfoHUD({ Corner = "Bottom Left", Watermark = "HawkTokai", Items = { "fps", "ping", "time" } })
--   info:SetCorner("Top Right")   info:SetItems({ "fps", "ping" })   info:SetVisible(false)   info:Destroy()
do
local okMod, errMod = pcall(function(Lib)
    if not Lib.UI then
        warn("[HawkTokai] InfoHud.lua needs Core.lua loaded first")
        return false
    end
    local UI = Lib.UI

    local TweenService = game:GetService("TweenService")
    local RunService = game:GetService("RunService")
    local Players = game:GetService("Players")
    local Stats = game:GetService("Stats")
    local MarketplaceService = game:GetService("MarketplaceService")

    local CORNERS = {
        ["Top Left"] = { anchor = Vector2.new(0, 0), x = 0, y = 0 },
        ["Top Right"] = { anchor = Vector2.new(1, 0), x = 1, y = 0 },
        ["Bottom Left"] = { anchor = Vector2.new(0, 1), x = 0, y = 1 },
        ["Bottom Right"] = { anchor = Vector2.new(1, 1), x = 1, y = 1 },
    }
    local LABELS = { fps = "fps", ping = "ping", time = "time", player = "user", game = "game", custom = "info" }
    local DEFAULT_ITEMS = { "fps", "ping", "time" }

    -- the place name is fetched once, in the background, and cached
    local gameName = nil
    task.spawn(function()
        local ok, info = pcall(function()
            return MarketplaceService:GetProductInfo(game.PlaceId)
        end)
        if ok and info and info.Name then
            gameName = info.Name
        end
    end)

    local function screenParent()
        local okHui, hui = pcall(function()
            if type(gethui) == "function" then
                return gethui()
            end
            return nil
        end)
        if okHui and typeof(hui) == "Instance" then
            return hui
        end
        local okCore, core = pcall(function()
            return game:GetService("CoreGui")
        end)
        if okCore and core then
            return core
        end
        return Players.LocalPlayer:WaitForChild("PlayerGui")
    end

    -- the network ping in ms, or nil when Roblox does not report it
    local function readPing()
        local ok, text = pcall(function()
            return Stats.Network.ServerStatsItem["Data Ping"]:GetValueString()
        end)
        if not ok or type(text) ~= "string" then
            return nil
        end
        local number = tonumber(string.match(text, "[%d%.]+"))
        if number == nil then
            return nil
        end
        return math.floor(number + 0.5)
    end

    function Lib:CreateInfoHUD(opts)
        opts = opts or {}
        local hud = {
            _destroyed = false,
            _visible = opts.Visible ~= false,
            _corner = CORNERS[opts.Corner] and opts.Corner or "Top Left",
            _margin = opts.Margin or 16,
            _custom = opts.Custom,
            _items = {},
            _conns = {},
            _frames = 0,
            _fps = 0,
            _fpsClock = os.clock(),
        }

        local gui = Instance.new("ScreenGui")
        gui.Name = "HawkTokaiInfo"
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 9001
        gui.IgnoreGuiInset = true
        gui.Enabled = hud._visible
        gui.Parent = screenParent()
        UI.track(gui)

        local panel = Instance.new("Frame")
        panel.Name = "Panel"
        panel.BackgroundColor3 = UI.color("Surface")
        panel.BackgroundTransparency = hud._visible and 0.12 or 1
        panel.BorderSizePixel = 0
        panel.Size = UDim2.fromOffset(190, 0)
        panel.AutomaticSize = Enum.AutomaticSize.Y
        panel.Parent = gui

        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 8)
        corner.Parent = panel
        local stroke = Instance.new("UIStroke")
        stroke.Color = UI.color("Stroke")
        stroke.Thickness = 1
        stroke.Parent = panel
        local padding = Instance.new("UIPadding")
        padding.PaddingTop = UDim.new(0, 8)
        padding.PaddingBottom = UDim.new(0, 8)
        padding.PaddingLeft = UDim.new(0, 10)
        padding.PaddingRight = UDim.new(0, 10)
        padding.Parent = panel
        local layout = Instance.new("UIListLayout")
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, 3)
        layout.Parent = panel

        local header = Instance.new("TextLabel")
        header.Name = "Watermark"
        header.BackgroundTransparency = 1
        header.Size = UDim2.new(1, 0, 0, 16)
        header.FontFace = UI.font("Bold")
        header.TextSize = 13
        header.TextColor3 = UI.color("Accent")
        header.TextXAlignment = Enum.TextXAlignment.Left
        header.Text = tostring(opts.Watermark or "HawkTokai")
        header.LayoutOrder = 0
        header.Parent = panel

        local function clearItems()
            for _, item in ipairs(hud._items) do
                item.label:Destroy()
            end
            table.clear(hud._items)
        end

        local function setItems(list)
            clearItems()
            for index, key in ipairs(list) do
                if LABELS[key] then
                    local row = Instance.new("TextLabel")
                    row.Name = key
                    row.BackgroundTransparency = 1
                    row.Size = UDim2.new(1, 0, 0, 15)
                    row.FontFace = UI.font("Regular")
                    row.TextSize = 13
                    row.TextColor3 = UI.color("Text")
                    row.TextXAlignment = Enum.TextXAlignment.Left
                    row.TextTruncate = Enum.TextTruncate.AtEnd
                    row.Text = ""
                    row.LayoutOrder = index
                    row.Parent = panel
                    table.insert(hud._items, { key = key, label = row })
                end
            end
        end

        local function valueOf(key)
            if key == "fps" then
                return tostring(hud._fps)
            elseif key == "ping" then
                local ping = readPing()
                if ping == nil then
                    return "--"
                end
                return tostring(ping) .. " ms"
            elseif key == "time" then
                return os.date("%H:%M:%S")
            elseif key == "player" then
                return Players.LocalPlayer.Name
            elseif key == "game" then
                return gameName or "..."
            elseif key == "custom" then
                local ok, value = pcall(function()
                    if type(hud._custom) == "function" then
                        return hud._custom()
                    end
                    return ""
                end)
                if ok then
                    return tostring(value)
                end
                return "error"
            end
            return ""
        end

        local function refresh()
            for _, item in ipairs(hud._items) do
                item.label.Text = LABELS[item.key] .. "  " .. valueOf(item.key)
            end
        end

        -- fps is the frame count of the last full second
        table.insert(hud._conns, RunService.RenderStepped:Connect(function()
            hud._frames += 1
            local now = os.clock()
            local span = now - hud._fpsClock
            if span >= 1 then
                hud._fps = math.floor(hud._frames / span + 0.5)
                hud._frames = 0
                hud._fpsClock = now
            end
        end))

        local warned = false
        task.spawn(function()
            while not hud._destroyed do
                if hud._visible then
                    local ok, err = pcall(refresh)
                    if not ok and not warned then
                        warned = true
                        warn("[HawkTokai] info hud refresh failed: " .. tostring(err))
                    end
                end
                task.wait(0.25)
            end
        end)

        local function place()
            local c = CORNERS[hud._corner]
            local m = hud._margin
            panel.AnchorPoint = c.anchor
            panel.Position = UDim2.new(c.x, c.x == 1 and -m or m, c.y, c.y == 1 and -m or m)
        end

        local function fade(on)
            hud._visible = on
            if on then
                gui.Enabled = true
                TweenService:Create(panel, TweenInfo.new(0.2, Enum.EasingStyle.Quint), { BackgroundTransparency = 0.12 }):Play()
            else
                TweenService:Create(panel, TweenInfo.new(0.2, Enum.EasingStyle.Quint), { BackgroundTransparency = 1 }):Play()
                task.delay(0.22, function()
                    if not hud._visible then
                        gui.Enabled = false
                    end
                end)
            end
        end

        function hud:SetCorner(name)
            if CORNERS[name] then
                hud._corner = name
                place()
            end
        end

        function hud:SetVisible(on)
            fade(on == true)
        end

        function hud:SetItems(list)
            setItems(type(list) == "table" and list or DEFAULT_ITEMS)
            refresh()
        end

        function hud:SetWatermark(text)
            header.Text = tostring(text or "")
            header.Visible = header.Text ~= ""
        end

        function hud:Destroy()
            hud._destroyed = true
            for _, connection in ipairs(hud._conns) do
                connection:Disconnect()
            end
            table.clear(hud._conns)
            gui:Destroy()
        end

        setItems(opts.Items or DEFAULT_ITEMS)
        place()
        fade(hud._visible)
        refresh()
        return hud
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] InfoHud failed: " .. tostring(errMod)) end
end
-- HawkTokai layout: sub-tabs inside one tab, and a settings group that opens under a toggle.
-- lives in its own file, so a bug here cannot stop HawkTokai.lua from loading.
-- usage: loadstring(readfile("HawkTokai/Layout.lua"))()(HawkTokai)
--   local subs = HawkTokai:AddSubTabs(tab, { "General", "Advanced" })  -- call right after CreateTab, before any element
--   subs[1]:CreateToggle({ Name = "..." })   subs:Select(2)
--   local group = HawkTokai:AddSettingsGroup(tab, someToggle)          -- elements added to group show while someToggle is on
do
local okMod, errMod = pcall(function(Lib)
    if not Lib.UI then
        warn("[HawkTokai] Layout.lua needs Core.lua loaded first")
        return false
    end
    local UI = Lib.UI
    local TweenService = game:GetService("TweenService")

    local FALLBACK = {
        Surface2 = Color3.fromRGB(30, 30, 38),
        Text = Color3.fromRGB(235, 235, 240),
        Muted = Color3.fromRGB(140, 140, 152),
    }

    -- reads the live theme, so a SetTheme call is picked up by the next sub-tab switch
    local function color(key)
        local theme = Lib.Theme
        local value = nil
        if type(theme) == "table" then
            value = theme[key]
        end
        if typeof(value) == "Color3" then
            return value
        end
        return FALLBACK[key]
    end

    local function tween(obj, seconds, props)
        return TweenService:Create(obj, TweenInfo.new(seconds, Enum.EasingStyle.Quint), props)
    end

    local function round(parent, radius)
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, radius)
        corner.Parent = parent
    end

    -- a proxy shares every method of the real tab (CreateToggle, CreateSlider, ...) but adds into another list
    local function proxyFor(tab, name, list)
        return setmetatable({
            Name = name,
            Window = tab.Window,
            _page = tab._page,
            _order = 0,
            List = list,
        }, getmetatable(tab))
    end

    function Lib:AddSubTabs(tab, names)
        local list = tab.List
        if typeof(list) ~= "Instance" or typeof(tab._page) ~= "Instance" or type(names) ~= "table" or #names == 0 then
            return nil
        end

        local headerY = list.Position.Y.Offset
        local listY = headerY + 40

        -- the segmented bar sits under the heading, one segment per sub-tab
        local bar = Instance.new("Frame")
        bar.Name = "SubTabs"
        bar.BackgroundTransparency = 1
        bar.Position = UDim2.fromOffset(24, headerY + 4)
        bar.Size = UDim2.new(1, -48, 0, 30)
        bar.ZIndex = 3
        bar.Parent = tab._page
        local row = Instance.new("UIListLayout")
        row.FillDirection = Enum.FillDirection.Horizontal
        row.SortOrder = Enum.SortOrder.LayoutOrder
        row.Padding = UDim.new(0, 4)
        row.Parent = bar

        -- the original list moves under the bar and stays hidden: every sub-tab has its own list
        list.Position = UDim2.fromOffset(0, listY)
        list.Size = UDim2.new(1, 0, 1, -listY)
        list.Visible = false

        local subs = {}
        local lists = {}
        local buttons = {}

        local function showSub(index)
            for i = 1, #lists do
                local active = i == index
                lists[i].Visible = active
                tween(buttons[i], 0.2, {
                    BackgroundTransparency = active and 0 or 1,
                    TextColor3 = active and color("Text") or color("Muted"),
                }):Play()
            end
        end

        for index, name in ipairs(names) do
            local sub = Instance.new("ScrollingFrame")
            sub.Name = "Sub_" .. tostring(name)
            sub.BackgroundTransparency = 1
            sub.BorderSizePixel = 0
            sub.ScrollBarThickness = list.ScrollBarThickness
            sub.ScrollBarImageColor3 = list.ScrollBarImageColor3
            sub.ScrollBarImageTransparency = list.ScrollBarImageTransparency
            sub.AutomaticCanvasSize = Enum.AutomaticSize.Y
            sub.CanvasSize = UDim2.new()
            sub.Position = list.Position
            sub.Size = list.Size
            sub.Visible = false
            sub.Parent = tab._page
            sub:SetAttribute("NoDrag", true)
            local padding = Instance.new("UIPadding")
            padding.PaddingLeft = UDim.new(0, 24)
            padding.PaddingRight = UDim.new(0, 24)
            padding.PaddingTop = UDim.new(0, 2)
            padding.PaddingBottom = UDim.new(0, 24)
            padding.Parent = sub
            local layout = Instance.new("UIListLayout")
            layout.SortOrder = Enum.SortOrder.LayoutOrder
            layout.Padding = UDim.new(0, 8)
            layout.Parent = sub
            lists[index] = sub

            local button = Instance.new("TextButton")
            button.Name = "Seg_" .. tostring(name)
            button.AutoButtonColor = false
            button.Text = tostring(name)
            button.FontFace = UI.font("Medium")
            button.TextSize = 13
            button.TextColor3 = color("Muted")
            button.BackgroundColor3 = color("Surface2")
            button.BackgroundTransparency = 1
            button.BorderSizePixel = 0
            button.Size = UDim2.new(0, 0, 1, 0)
            button.AutomaticSize = Enum.AutomaticSize.X
            button.LayoutOrder = index
            button.ZIndex = 4
            button.Parent = bar
            round(button, 6)
            local buttonPad = Instance.new("UIPadding")
            buttonPad.PaddingLeft = UDim.new(0, 12)
            buttonPad.PaddingRight = UDim.new(0, 12)
            buttonPad.Parent = button
            buttons[index] = button
            button.MouseButton1Click:Connect(function()
                showSub(index)
            end)

            subs[index] = proxyFor(tab, tostring(name), sub)
        end

        function subs:Select(index)
            if type(index) == "number" and lists[index] then
                showSub(index)
            end
        end

        UI.linkEmpty(tab, lists)
        showSub(1)
        return subs
    end

    function Lib:AddSettingsGroup(tab, toggle)
        local list = tab.List
        if typeof(list) ~= "Instance" or type(toggle) ~= "table" or type(toggle.Get) ~= "function" then
            return nil
        end

        local group = Instance.new("Frame")
        group.Name = "SettingsGroup"
        group.BackgroundTransparency = 1
        group.BorderSizePixel = 0
        group.Size = UDim2.new(1, 0, 0, 0)
        group.AutomaticSize = Enum.AutomaticSize.Y
        group.LayoutOrder = tab:_nextOrder()
        group.Parent = list
        local padding = Instance.new("UIPadding")
        padding.PaddingLeft = UDim.new(0, 18)
        padding.PaddingTop = UDim.new(0, 2)
        padding.PaddingBottom = UDim.new(0, 2)
        padding.Parent = group
        local layout = Instance.new("UIListLayout")
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, 8)
        layout.Parent = group

        local function isOn()
            local ok, on = pcall(function()
                return toggle:Get() == true
            end)
            return ok and on == true
        end

        group.Visible = isOn()
        task.spawn(function()
            while group.Parent do
                local on = isOn()
                if group.Visible ~= on then
                    group.Visible = on
                end
                task.wait(0.1)
            end
        end)

        return proxyFor(tab, "settings", group)
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Layout failed: " .. tostring(errMod)) end
end
-- HawkTokai look: a dot-grid texture behind the whole window (borrowed idea from Millennium's background pattern, written fresh).
-- the dot tile is built into this file and written to the workspace the first time it is needed.
-- part of HawkTokai.lua. needs getcustomasset in the executor.
-- usage: local dots = HawkTokai:AddBackgroundPattern(Window, { Opacity = 0.12, Tile = 32 })   dots.Visible = false
do
local okMod, errMod = pcall(function(Lib)
    if not Lib.UI then
        warn("[HawkTokai] Look needs Core first")
        return false
    end
    local UI = Lib.UI

    local DEFAULT_PATH = "HawkTokai/assets/dots.png"
    local DOTS_PNG = "\137\080\078\071\013\010\026\010\000\000\000\013\073\072\068\082\000\000\000\032\000\000\000\032\008\006\000\000\000\115\122\122\244\000\000\000\035\073\068\065\084\120\218\237\206\049\017\000\000\008\004\160\239\095\090\023\035\184\120\066\002\018\000\224\178\026\127\003\000\192\134\006\150\160\015\241\216\228\047\021\000\000\000\000\073\069\078\068\174\066\096\130"

    -- makes sure the tile is on disk. false when the executor has no file API
    local function ensureTile(path)
        if type(isfile) == "function" and isfile(path) then
            return true
        end
        if type(writefile) ~= "function" then
            return false
        end
        local folder = string.match(path, "^(.*)/[^/]+$")
        if folder and type(isfolder) == "function" and type(makefolder) == "function" then
            local built = nil
            for part in string.gmatch(folder, "[^/]+") do
                built = built and (built .. "/" .. part) or part
                if not isfolder(built) then
                    pcall(makefolder, built)
                end
            end
        end
        return (pcall(writefile, path, DOTS_PNG))
    end

    function Lib:AddBackgroundPattern(Window, opts)
        opts = opts or {}
        local body = Window.Body
        if typeof(body) ~= "Instance" then
            return nil
        end
        if type(getcustomasset) ~= "function" then
            warn("[HawkTokai] background pattern needs getcustomasset")
            return nil
        end
        local path = opts.Path or DEFAULT_PATH
        if not ensureTile(path) then
            warn("[HawkTokai] background pattern: cannot write " .. path)
            return nil
        end
        local okAsset, asset = pcall(getcustomasset, path)
        if not okAsset or type(asset) ~= "string" then
            warn("[HawkTokai] background pattern not loaded: " .. tostring(asset))
            return nil
        end
        local opacity = math.clamp(tonumber(opts.Opacity) or 0.12, 0, 1)
        local tile = math.max(tonumber(opts.Tile) or 32, 4)
        local pattern = Instance.new("ImageLabel")
        pattern.Name = "BackgroundPattern"
        pattern.BackgroundTransparency = 1
        pattern.Size = UDim2.fromScale(1, 1)
        pattern.Image = asset
        pattern.ScaleType = Enum.ScaleType.Tile
        pattern.TileSize = UDim2.fromOffset(tile, tile)
        pattern.ImageColor3 = UI.color("Accent")
        pattern.ImageTransparency = 1 - opacity
        pattern.Active = false
        pattern.ZIndex = 0
        pattern.Parent = body
        return pattern
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Look failed: " .. tostring(errMod)) end
end
-- HawkTokai autoload: remembers one config name in a file and loads it when the window is built.
-- borrowed idea from Millennium's autoload config (written fresh). lives in its own file, so a bug here cannot stop HawkTokai.lua from loading.
-- usage: loadstring(readfile("HawkTokai/Autoload.lua"))()(HawkTokai)
--        HawkTokai:AddAutoload(Window, tab)   -- loads the saved name now, adds Config / Set / Clear controls to tab
do
local okMod, errMod = pcall(function(Lib)
    local DEFAULT_FOLDER = "HawkTokai"
    local FILE_NAME = "autoload.txt"

    local function pathFor(folder)
        return folder .. "/" .. FILE_NAME
    end

    -- the saved config name, or nil when nothing is saved
    local function readSaved(folder)
        if type(isfile) ~= "function" or type(readfile) ~= "function" then
            return nil
        end
        local path = pathFor(folder)
        local okExists, exists = pcall(isfile, path)
        if not okExists or not exists then
            return nil
        end
        local ok, text = pcall(readfile, path)
        if ok and type(text) == "string" and text ~= "" then
            return text
        end
        return nil
    end

    local function writeSaved(folder, name)
        if type(writefile) ~= "function" then
            return false, "writefile is not available"
        end
        if type(isfolder) == "function" and type(makefolder) == "function" then
            local okFolder, exists = pcall(isfolder, folder)
            if okFolder and not exists then
                pcall(makefolder, folder)
            end
        end
        local ok, err = pcall(writefile, pathFor(folder), name)
        return ok, err
    end

    -- Lib:Notify is part of HawkTokai; the pcall keeps a missing notify from breaking a button
    local function notify(title, content)
        pcall(function()
            Lib:Notify({ Title = title, Content = content, Duration = 3 })
        end)
    end

    function Lib:AddAutoload(Window, tab, opts)
        opts = opts or {}
        local folder = opts.Folder or Window.ConfigFolder or DEFAULT_FOLDER
        local saved = readSaved(folder)

        -- load the saved config now, so it wins over a default load that ran before this call
        if saved and type(Window.LoadConfig) == "function" then
            local ok, success, reason = pcall(function()
                return Window:LoadConfig(saved)
            end)
            if not ok then
                warn("[HawkTokai] autoload failed: " .. tostring(success))
            elseif success == false then
                warn("[HawkTokai] autoload failed: " .. tostring(reason))
            end
        end

        if not tab or typeof(tab.List) ~= "Instance" then
            return { Name = saved, Path = pathFor(folder) }
        end

        local choice = saved
        local options = {}
        if type(Window.ListConfigs) == "function" then
            local okList, names = pcall(function()
                return Window:ListConfigs()
            end)
            if okList and type(names) == "table" then
                options = names
            end
        end

        tab:CreateSection("Autoload")
        local dropdown = tab:CreateDropdown({
            Name = "Config",
            Options = options,
            Default = saved,
            Callback = function(value)
                choice = value
            end,
        })
        -- the list follows the configs in the folder, so a config saved later shows up without a rebuild
        local shown = table.concat(options, "\n")
        local function refreshNames()
            if type(Window.ListConfigs) ~= "function" then
                return
            end
            local okList, names = pcall(function()
                return Window:ListConfigs()
            end)
            if not okList or type(names) ~= "table" then
                return
            end
            local joined = table.concat(names, "\n")
            if joined ~= shown then
                shown = joined
                pcall(function()
                    dropdown:Refresh(names, true)
                end)
            end
        end
        task.spawn(function()
            while tab.List.Parent ~= nil do
                refreshNames()
                task.wait(2)
            end
        end)
        tab:CreateButton({
            Name = "Set as autoload",
            Icon = "zap",
            Callback = function()
                if not choice or choice == "" then
                    return
                end
                local ok, err = writeSaved(folder, tostring(choice))
                if ok then
                    saved = tostring(choice)
                    notify("autoload set", saved)
                else
                    notify("autoload failed", tostring(err))
                end
            end,
        })
        tab:CreateButton({
            Name = "Clear autoload",
            Style = "Danger",
            Callback = function()
                local ok, err = writeSaved(folder, "")
                if ok then
                    saved = nil
                    notify("autoload cleared", "")
                else
                    notify("clear failed", tostring(err))
                end
            end,
        })

        return { Name = saved, Path = pathFor(folder) }
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Autoload failed: " .. tostring(errMod)) end
end
-- HawkTokai columns: split one tab into side-by-side columns. each column is a proxy tab, so every element works in it.
-- clean-room layout, written fresh. lives in its own file, so a bug here cannot stop HawkTokai.lua from loading.
-- usage: loadstring(readfile("HawkTokai/Columns.lua"))()(HawkTokai)
--   local cols = HawkTokai:AddColumns(tab, 2)   -- call right after CreateTab, before any element
--   cols[1]:CreateToggle({ Name = "..." })      cols[2]:CreateSlider({ Name = "...", Min = 0, Max = 10 })
do
local okMod, errMod = pcall(function(Lib)
    local MAX_COLUMNS = 4
    local EDGE = 24
    local DEFAULT_GAP = 12

    -- a proxy shares every method of the real tab but adds into another list
    local function proxyFor(tab, name, list)
        return setmetatable({
            Name = name,
            Window = tab.Window,
            _page = tab._page,
            _order = 0,
            List = list,
        }, getmetatable(tab))
    end

    function Lib:AddColumns(tab, count, opts)
        opts = opts or {}
        local list = tab.List
        if typeof(list) ~= "Instance" or typeof(tab._page) ~= "Instance" then
            return nil
        end
        count = math.clamp(math.floor(tonumber(count) or 2), 1, MAX_COLUMNS)
        local gap = tonumber(opts.Gap) or DEFAULT_GAP
        local headerY = list.Position.Y.Offset

        -- the original list stays hidden; each column is its own scrolling list under the heading
        list.Visible = false

        local columns = {}
        local lists = {}
        for index = 1, count do
            local left = index == 1 and EDGE or math.floor(gap / 2)
            local right = index == count and EDGE or math.floor(gap / 2)

            local column = Instance.new("ScrollingFrame")
            column.Name = "Column" .. index
            column.BackgroundTransparency = 1
            column.BorderSizePixel = 0
            column.ScrollBarThickness = list.ScrollBarThickness
            column.ScrollBarImageColor3 = list.ScrollBarImageColor3
            column.ScrollBarImageTransparency = list.ScrollBarImageTransparency
            column.AutomaticCanvasSize = Enum.AutomaticSize.Y
            column.CanvasSize = UDim2.new()
            column.Position = UDim2.new((index - 1) / count, left, 0, headerY)
            column.Size = UDim2.new(1 / count, -(left + right), 1, -headerY)
            column:SetAttribute("NoDrag", true)
            column.Parent = tab._page

            local padding = Instance.new("UIPadding")
            padding.PaddingTop = UDim.new(0, 2)
            padding.PaddingBottom = UDim.new(0, 24)
            padding.Parent = column
            local layout = Instance.new("UIListLayout")
            layout.SortOrder = Enum.SortOrder.LayoutOrder
            layout.Padding = UDim.new(0, 8)
            layout.Parent = column

            columns[index] = proxyFor(tab, "column" .. index, column)
            table.insert(lists, column)
        end
        if Lib.UI then
            Lib.UI.linkEmpty(tab, lists)
        end
        return columns
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Columns failed: " .. tostring(errMod)) end
end
-- HawkTokai lists: a searchable toggle list and a reorderable list, built from Airflow's own toggles and buttons.
-- both take Flag, so SaveConfig and LoadConfig carry them, and both run the autosave after a change.
-- lives in its own file, so a bug here cannot stop HawkTokai.lua from loading. needs Core.lua first.
-- usage: loadstring(readfile("HawkTokai/Lists.lua"))()(HawkTokai)
--   local picks = HawkTokai:AddSearchableToggleList(tab, { Items = {...}, Default = {...}, Flag = "picks", Callback = function(names) end })
--   picks:Get()   picks:Set(names, skipCallback)   picks:Filter(text)
--   local order = HawkTokai:AddReorderableList(tab, { Items = {...}, Flag = "order", Callback = function(names) end })
--   order:Get()   order:Set(names, skipCallback)   -- drag a row by its card to move it
do
local okMod, errMod = pcall(function(Lib)
    if not Lib.UI then
        warn("[HawkTokai] Lists.lua needs Core.lua loaded first")
        return false
    end
    local UI = Lib.UI

    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")

    -- a proxy shares every method of the real tab but adds into another list
    local function proxyFor(tab, name, list)
        return setmetatable({
            Name = name,
            Window = tab.Window,
            _page = tab._page,
            _order = 0,
            List = list,
        }, getmetatable(tab))
    end

    -- one container in the tab's flow, so the list sits between the other elements of the page
    local function containerFor(tab, name)
        local container = Instance.new("Frame")
        container.Name = name
        container.BackgroundTransparency = 1
        container.BorderSizePixel = 0
        container.Size = UDim2.new(1, 0, 0, 0)
        container.AutomaticSize = Enum.AutomaticSize.Y
        container.LayoutOrder = tab:_nextOrder()
        container.Parent = tab.List
        local layout = Instance.new("UIListLayout")
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, 8)
        layout.Parent = container
        return container
    end

    local function setStroke(card, color)
        local stroke = card:FindFirstChildOfClass("UIStroke")
        if stroke then
            stroke.Color = color
        end
    end

    local function sameNames(a, b)
        if #a ~= #b then
            return false
        end
        for index = 1, #a do
            if a[index] ~= b[index] then
                return false
            end
        end
        return true
    end

    function Lib:AddSearchableToggleList(tab, opts)
        opts = opts or {}
        local flag = opts.Flag
        local items = opts.Items or {}
        local selected = {}
        for _, name in ipairs(opts.Default or {}) do
            selected[tostring(name)] = true
        end

        local container = containerFor(tab, "SearchableList")
        local proxy = proxyFor(tab, "list", container)
        local api = {}
        local order = {}
        local rows = {}
        local ready = false

        local function picked()
            local out = {}
            for _, name in ipairs(order) do
                if selected[name] then
                    table.insert(out, name)
                end
            end
            return out
        end

        -- rows stay on screen when their name contains the filter text
        local function applyFilter(text)
            local query = string.lower(tostring(text or ""))
            for _, name in ipairs(order) do
                local handle = rows[name]
                local frame = handle and handle._frame
                if frame then
                    frame.Visible = query == "" or string.find(string.lower(name), query, 1, true) ~= nil
                end
            end
        end

        -- runs the callback and the autosave, but only when the selection really changed
        local function announce(before)
            if not ready then
                return
            end
            local now = picked()
            if sameNames(before, now) then
                return
            end
            if opts.Callback then
                pcall(opts.Callback, now)
            end
            UI.changed(tab.Window, flag)
        end

        proxy:CreateInput({
            Name = "Filter",
            Placeholder = "type to filter",
            OnChanged = applyFilter,
        })

        for _, item in ipairs(items) do
            local name = tostring(item)
            table.insert(order, name)
            rows[name] = proxy:CreateToggle({
                Name = name,
                Default = selected[name] == true,
                Callback = function(value)
                    if not ready then
                        return
                    end
                    local before = picked()
                    selected[name] = value and true or nil
                    announce(before)
                end,
            })
        end
        ready = true

        function api:Get()
            return picked()
        end

        -- skipCallback is true when the value comes from LoadConfig, so nothing runs twice
        function api:Set(names, skipCallback)
            local before = picked()
            table.clear(selected)
            for _, name in ipairs(names or {}) do
                selected[tostring(name)] = true
            end
            for _, name in ipairs(order) do
                local handle = rows[name]
                if handle then
                    handle:Set(selected[name] == true, true)
                end
            end
            if skipCallback ~= true then
                announce(before)
            end
        end

        function api:Filter(text)
            applyFilter(text)
        end

        UI.register(tab.Window, api, flag, "SearchList")
        return api
    end

    function Lib:AddReorderableList(tab, opts)
        opts = opts or {}
        local flag = opts.Flag
        local container = containerFor(tab, "ReorderableList")
        local proxy = proxyFor(tab, "reorder", container)
        local api = {}
        local rows = {}
        local dragging = nil
        local startNames = nil
        local ready = false

        local function namesNow()
            local out = {}
            for _, row in ipairs(rows) do
                table.insert(out, row.name)
            end
            return out
        end

        -- the layout sorts by LayoutOrder, so renumbering the rows moves the cards
        local function relayout()
            for index, row in ipairs(rows) do
                if row.card then
                    row.card.LayoutOrder = index
                end
            end
        end

        -- the slot under the pointer: the first row whose centre is below the pointer
        local function slotAt(y)
            for index, row in ipairs(rows) do
                local card = row.card
                if card and y < card.AbsolutePosition.Y + card.AbsoluteSize.Y / 2 then
                    return index
                end
            end
            return #rows
        end

        local function moveRow(row, target)
            local current = table.find(rows, row)
            if not current or current == target then
                return
            end
            table.remove(rows, current)
            table.insert(rows, target, row)
            relayout()
        end

        -- runs the callback and the autosave, but only when the order really changed
        local function announce(before)
            if not ready then
                return
            end
            local now = namesNow()
            if sameNames(before, now) then
                return
            end
            if opts.Callback then
                pcall(opts.Callback, now)
            end
            UI.changed(tab.Window, flag)
        end

        for _, item in ipairs(opts.Items or {}) do
            local name = tostring(item)
            local handle = proxy:CreateButton({
                Name = name,
                Icon = "menu",
            })
            local row = { name = name, card = handle._frame }
            table.insert(rows, row)
            if row.card then
                row.card.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        dragging = row
                        startNames = namesNow()
                        setStroke(row.card, UI.color("Accent"))
                    end
                end)
            end
        end
        relayout()
        ready = true

        RunService.RenderStepped:Connect(function()
            if dragging then
                moveRow(dragging, slotAt(UserInputService:GetMouseLocation().Y))
            end
        end)

        UserInputService.InputEnded:Connect(function(input)
            if not dragging then
                return
            end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            local row = dragging
            dragging = nil
            if row.card then
                setStroke(row.card, UI.color("Stroke"))
            end
            announce(startNames)
        end)

        function api:Get()
            return namesNow()
        end

        -- skipCallback is true when the order comes from LoadConfig, so nothing runs twice
        function api:Set(names, skipCallback)
            local before = namesNow()
            local byName = {}
            for _, row in ipairs(rows) do
                byName[row.name] = row
            end
            local newRows = {}
            for _, name in ipairs(names or {}) do
                local row = byName[tostring(name)]
                if row and not table.find(newRows, row) then
                    table.insert(newRows, row)
                end
            end
            -- a row the new order did not mention keeps its place at the end
            for _, row in ipairs(rows) do
                if not table.find(newRows, row) then
                    table.insert(newRows, row)
                end
            end
            rows = newRows
            relayout()
            if skipCallback ~= true then
                announce(before)
            end
        end

        UI.register(tab.Window, api, flag, "ReorderList")
        return api
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Lists failed: " .. tostring(errMod)) end
end
-- HawkTokai sections: a toggle section, a window opacity slider and a cursor override.
-- clean-room, written fresh. lives in its own file, so a bug here cannot stop HawkTokai.lua from loading.
-- AddToggleSection needs Layout.lua. usage: loadstring(readfile("HawkTokai/Sections.lua"))()(HawkTokai)
--   local toggle, group = HawkTokai:AddToggleSection(tab, { Name = "Aim assist", Default = false, Flag = "sec_aim" })
--   group:CreateSlider({ Name = "Strength", Min = 0, Max = 100 })
--   HawkTokai:AddWindowOpacity(Window, tab, { Default = 100 })
--   local cursor = HawkTokai:AddCursorOverride(Window)   cursor:SetEnabled(false)
do
local okMod, errMod = pcall(function(Lib)
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")

    -- a toggle, and a settings group that shows only while the toggle is on
    function Lib:AddToggleSection(tab, opts)
        opts = opts or {}
        local toggle = tab:CreateToggle({
            Name = tostring(opts.Name or "Section"),
            Default = opts.Default == true,
            Flag = opts.Flag,
            Callback = opts.Callback,
        })
        if type(Lib.AddSettingsGroup) ~= "function" then
            warn("[HawkTokai] AddToggleSection needs Layout.lua")
            return toggle, nil
        end
        local group = Lib:AddSettingsGroup(tab, toggle)
        return toggle, group
    end

    -- one slider that sets the window background opacity. 20 percent is the floor, so the window never disappears
    function Lib:AddWindowOpacity(Window, tab, opts)
        opts = opts or {}
        local body = Window.Body
        if typeof(body) ~= "Instance" or not tab then
            return nil
        end
        local function apply(value)
            local percent = math.clamp(tonumber(value) or 100, 20, 100)
            body.BackgroundTransparency = 1 - percent / 100
        end
        local slider = tab:CreateSlider({
            Name = tostring(opts.Name or "Window opacity"),
            Min = 20,
            Max = 100,
            Default = tonumber(opts.Default) or 100,
            Suffix = "%",
            Flag = opts.Flag,
            Callback = apply,
        })
        apply(opts.Default or 100)
        return slider
    end

    -- keeps the cursor free while the window is open, since some games lock or hide it.
    -- the previous cursor state is saved on open and put back on close or Destroy.
    function Lib:AddCursorOverride(Window)
        local enabled = true
        local saved = nil
        local api = {}

        local connection = RunService.RenderStepped:Connect(function()
            local open = Window.Open == true
            if enabled and open then
                if saved == nil then
                    saved = { behavior = UserInputService.MouseBehavior, icon = UserInputService.MouseIconEnabled }
                end
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                UserInputService.MouseIconEnabled = true
            elseif saved ~= nil then
                UserInputService.MouseBehavior = saved.behavior
                UserInputService.MouseIconEnabled = saved.icon
                saved = nil
            end
        end)

        function api:SetEnabled(on)
            enabled = on == true
        end

        function api:Destroy()
            connection:Disconnect()
            if saved ~= nil then
                UserInputService.MouseBehavior = saved.behavior
                UserInputService.MouseIconEnabled = saved.icon
                saved = nil
            end
        end

        return api
    end

    return true
end, HawkTokaiLib)
if not okMod then warn("[HawkTokai] Sections failed: " .. tostring(errMod)) end
end

return HawkTokaiLib
